describe('Modal with Tabbed Content - Active Tab Persistence', () => {
  beforeEach(() => {
    cy.visit('/modal-tabs');
  });

  it('should display modal with tabbed content and remember the active tab', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify initial tab is displayed
    cy.get('[data-testid="tab-1"]').should('be.visible');
    cy.get('[data-testid="tab-1"]').should('contain', 'Tab 1 Content');

    // Verify tab 2 is not visible
    cy.get('[data-testid="tab-2"]').should('not.be.visible');

    // Click on tab 2
    cy.get('[data-testid="tab-2"]').click();

    // Verify tab 2 is now active
    cy.get('[data-testid="tab-2"]').should('be.visible');
    cy.get('[data-testid="tab-2"]').should('contain', 'Tab 2 Content');

    // Verify tab 1 is hidden
    cy.get('[data-testid="tab-1"]').should('not.be.visible');

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should maintain active tab state after reopening modal with different tab selection', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Click on tab 3
    cy.get('[data-testid="tab-3"]').click();
    cy.get('[data-testid="tab-3"]').should('be.visible');
    cy.get('[data-testid="tab-3"]').should('contain', 'Tab 3 Content');

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();

    // Reopen modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Verify tab 3 is still active
    cy.get('[data-testid="tab-3"]').should('be.visible');
    cy.get('[data-testid="tab-3"]').should('contain', 'Tab 3 Content');

    // Verify other tabs are hidden
    cy.get('[data-testid="tab-1"]').should('not.be.visible');
    cy.get('[data-testid="tab-2"]').should('not.be.visible');

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });
});
